/**
 * @file class-hazards.ts — Per-product-class FMEA / hazard registry.
 *
 * Universal Principle (Tristan directive 2026-05-15): risk and FMEA content
 * is class-universal, not BoM-derived. The hazards a BESS or CGM or HAPS
 * faces exist at the CLASS level (chemistry, environment, operating mode)
 * regardless of how dense the BoM emission was for any particular brief.
 *
 * Sibling of class-floors.ts + class-standards.ts. The standalone §Risk page
 * reads from this registry and overlays brief-specific operating environment
 * to produce a hazard table with severity × likelihood × detectability RPN
 * scores per entry, plus typical mitigations linked back to class-standards.
 *
 * Each entry is a CLASS-LEVEL hazard — the failure mode every product in
 * this class needs to think about. Design-specific FMEA (specific to chosen
 * cell chemistry / refrigerant / sensor architecture) is layered on top at
 * design time.
 *
 * Scoring conventions (1-5 scale at class level — coarser than ISO 14971's
 * 1-10 because class-level data lacks the resolution for finer grading):
 *   severity:   1 = negligible · 2 = minor · 3 = serious · 4 = critical · 5 = catastrophic
 *   likelihood: 1 = remote     · 2 = rare  · 3 = occasional · 4 = frequent · 5 = continuous
 *   RPN = severity × likelihood × detectability_difficulty (1-5 where 5 = hard to detect)
 */

export type HazardCategory =
  | 'thermal'
  | 'electrical'
  | 'mechanical'
  | 'chemical'
  | 'biological'
  | 'software'
  | 'cybersecurity'
  | 'data_protection'
  | 'environmental'
  | 'operational'
  | 'human_factors'
  | 'radiation'

export interface ClassHazard {
  /** Stable short code for cross-referencing (e.g. "THR-01" for energy_storage thermal-runaway-1). */
  code: string
  title: string
  category: HazardCategory
  /** Pre-mitigation severity rating, 1-5. */
  severity_pre: 1 | 2 | 3 | 4 | 5
  /** Pre-mitigation likelihood rating, 1-5. */
  likelihood_pre: 1 | 2 | 3 | 4 | 5
  /** Detectability difficulty, 1-5. Higher = harder to detect before harm. */
  detectability: 1 | 2 | 3 | 4 | 5
  /** One-sentence description of the hazard mechanism. */
  mechanism: string
  /** Design / process mitigations typical in this class (ordered most-to-least common). */
  common_mitigations: string[]
  /** Runtime / production detection methods (sensors, surveillance, sampling). */
  detection_methods: string[]
  /** class-standards codes that govern or test this hazard. */
  regulatory_drivers: string[]
  /** How the hazard is typically verified in qualification testing. */
  typical_test_method: string
}

export interface ClassHazards {
  product_class: string
  display_name: string
  hazards: ClassHazard[]
  /** One-sentence summary of the class's hazard landscape, used in §Risk page intro. */
  hazard_summary: string
}

