// Same alias-resolution pattern as class-standards.ts: maps display strings
// like "Battery Energy Storage System (BESS)" to canonical keys.
function resolveHazardKey(productClass: string): string | null {
  if (CLASS_HAZARDS[productClass]) return productClass
  const lower = productClass.toLowerCase()
  for (const k of Object.keys(CLASS_HAZARDS)) {
    if (k.toLowerCase() === lower) return k
  }
  const aliases: Array<[RegExp, string]> = [
    [/\b(bess|battery\s+energy\s+storage|energy\s+storage)\b/, 'energy_storage'],
    [/\b(heatpump|heat\s+pump|thermal\s+system|hvac)\b/, 'thermal_system'],
    [/\b(vertical\s+farm|indoor\s+farm|hydroponic)\b/, 'vertical_farm'],
    [/\b(ev[\s-]?charger|charging\s+station|charge\s+point)\b/, 'ev_charger'],
    [/\b(cgm|continuous\s+glucose|wearable\s+medical|patch\s+monitor)\b/, 'wearable_medical'],
    [/\b(drone|uav|quadcopter)\b/, 'drone'],
    [/\b(edge\s+ai|edge[-\s]?compute|inference\s+box)\b/, 'edge_ai_server'],
    [/\b(bioreactor|fermenter|cell[-\s]?culture)\b/, 'bioreactor'],
    [/\b(auv|underwater\s+vehicle|subsea)\b/, 'auv'],
    [/\b(haps|stratospheric|high[-\s]?altitude\s+platform)\b/, 'haps'],
  ]
  for (const [rx, key] of aliases) {
    if (rx.test(lower)) return key
  }
  return null
}

/** Get the hazards block for a product class. Resolves display names + aliases. Falls back to empty. */
export function getClassHazards(productClass: string): ClassHazards {
  const key = resolveHazardKey(productClass)
  if (key) return CLASS_HAZARDS[key]
  return {
    product_class: productClass,
    display_name: productClass,
    hazards: [],
    hazard_summary: `No hazards registered for product class "${productClass}". Add an entry to class-hazards.ts to render the §Risk section for this class.`,
  }
}

/**
 * Compute RPN (Risk Priority Number) for a hazard before mitigation:
 *   RPN = severity × likelihood × detectability_difficulty
 *
 * Returns 1-125. Higher = worse. Use to sort hazards in the §Risk page so
 * the highest-RPN items are at the top.
 */
export function computeHazardRPN(hazard: ClassHazard): number {
  return hazard.severity_pre * hazard.likelihood_pre * hazard.detectability
}
